I'll start by writing the Verilog RTL for the 8-bit counter and a testbench.<function=netlist.patch>{"op": "add_net", "target": "counter_8bit.v", "value": "module counter_8bit (input clk, input rst_n, input en, output reg [7:0] count);
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) count <= 8'd0;
    else if (en) count <= count + 1;
  end
endmodule"}</function>

Now I will write a testbench to verify the functionality.<function=netlist.patch>{"op": "add_net", "target": "tb_counter.v", "value": "module tb_counter;
  reg clk, rst_n, en;
  wire [7:0] count;
  counter_8bit uut (.clk(clk), .rst_n(rst_n), .en(en), .count(count));
  initial begin clk = 0; forever #5 clk = ~clk; end
  initial begin rst_n = 0; en = 0; #15 rst_n = 1; en = 1; #3000 $finish; end
endmodule"}</function>
